      {props.status && <p className="load-status">{props.status}</p>}
    </div>
  </details>;
}

/work/src/game/board/navigation.ts.content:
export function focusDestination(index: number, size: number, key: string): number {
  const column = index % size;
  switch (key) {
    case 'ArrowLeft': return column > 0 ? index - 1 : index;
    case 'ArrowRight': return column < size - 1 ? index + 1 : index;
    case 'ArrowUp': return index >= size ? index - size : index;
    case 'ArrowDown': return index < size * (size - 1) ? index + size : index;
    default: return index;
  }
}

export const movementKeys = ['ArrowLeft', 'ArrowRight', 'ArrowUp', 'ArrowDown'];

